PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, registered INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL, auth_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS credentials(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, public_key TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS challenges(id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, value TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS friends(id TEXT PRIMARY KEY, sender TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('pending','accepted')), created INTEGER NOT NULL, CHECK(sender<>recipient));
CREATE UNIQUE INDEX IF NOT EXISTS friend_pair ON friends(min(sender,recipient),max(sender,recipient));
CREATE TABLE IF NOT EXISTS blocks(actor TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, target TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(actor,target), CHECK(actor<>target));
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY, sender TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, code TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','accepted','declined')), expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS invites_recipient ON invites(recipient,expires);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY, actor TEXT REFERENCES users(id) ON DELETE SET NULL, target TEXT REFERENCES users(id) ON DELETE SET NULL, reason TEXT NOT NULL, detail TEXT NOT NULL, match_id TEXT, created INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS matches(id TEXT PRIMARY KEY, host TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, guest TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, settings TEXT NOT NULL, round INTEGER NOT NULL DEFAULT 1, hp_host INTEGER NOT NULL, hp_guest INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending', winner TEXT REFERENCES users(id), created INTEGER NOT NULL, CHECK(host<>guest));
CREATE INDEX IF NOT EXISTS matches_players ON matches(host,guest,state);
CREATE TABLE IF NOT EXISTS turns(match_id TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE, round INTEGER NOT NULL, player TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, commitment TEXT NOT NULL, revealed INTEGER NOT NULL DEFAULT 0, value INTEGER, PRIMARY KEY(match_id,round,player));
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY, n INTEGER NOT NULL, until INTEGER NOT NULL);
